    filename = request.args.get('filename', '')

    # Security check: Ensure the filename is not empty and starts with a valid path separator
    if not filename or not filename.startswith('./'):
        flash('Invalid filename provided.', 'error')
        return redirect(url_for('index'))

    # Construct the full file path
    filepath = os.path.join(DATA_DIR, filename)

    # Security check: Verify the file exists and is a regular file
    if not os.path.exists(filepath):
        flash(f'File not found: {filename}', 'error')
        return redirect(url_for('index'))

    if not os.path.isfile(filepath):
        flash('Path does not point to a regular file.', 'error')
        return redirect(url_for('index'))

    try:
        # Read the file contents safely
        with open(filepath, 'rb') as f:
            content = f.read()

        # Return the binary content as bytes
        return content
    except IOError as e:
        flash(f'Error reading file: {e}', 'error')
        return redirect(url_for('index'))

