import subprocess

def count_lines(path):
    """
    Returns the number of lines in the text file at path by running 'wc -l'.

    Parameters:
        path (str): Path to the text file

    Returns:
        int: Number of lines in the file
    """
    try:
        result = subprocess.run(
            ['wc', '-l', path],
            capture_output=True,
            text=True,
            check=False
        )

        if result.returncode == 0:
            return int(result.stdout.strip())
        else:
            raise ValueError("Failed to read file or command failed")
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {path}")
    except PermissionError:
        raise PermissionError("Permission denied while reading the file")
    except Exception as e:
        raise RuntimeError(f"An error occurred while counting lines: {e}")
