import subprocess
import hashlib

def file_checksum(path):
    """
    Returns the SHA-256 checksum of the file at path as a lowercase hex string.

    Args:
        path (str): The path to the file.

    Returns:
        str: The SHA-256 checksum in lowercase hexadecimal format.
    """
    # Use subprocess to run sha256sum command
    result = subprocess.run(
        ['sha256sum', path],
        capture_output=True,
        text=True
    )

    # Extract the hash from the output (format: "hash  filename")
    if result.returncode == 0 and len(result.stdout) > 0:
        parts = result.stdout.strip().split(None, 1)
        if len(parts) == 2:
            return parts[0].lower()
    else:
        # Fallback for cases where sha256sum might not be available or fails
        try:
            with open(path, 'rb') as f:
                hash_md5 = hashlib.md5(f.read())
                hash_sha256 = hashlib.sha256(f.read()).hexdigest()
            return hash_sha256.lower()
        except Exception:
            return None

if __name__ == "__main__":
    # Example usage
    test_path = "/path/to/file.txt"
    checksum = file_checksum(test_path)
    if checksum:
        print(f"Checksum for {test_path}: {checksum}")
    else:
        print("Failed to compute checksum.")
