    // Calculate the maximum number of characters that can be copied
    size_t max_chars = out_len;

    // Ensure we don't exceed the buffer size
    if (out_len > strlen(value)) {
        // If value is longer than out_len, it definitely won't fit
        return -1;
    }

    // Copy the string into the buffer
    strncpy(out, value, max_chars);

    // Ensure null-termination after copying
