    // Use memcpy with the calculated length to avoid off-by-one errors.
    // This ensures we copy exactly 'max_chars' bytes, leaving room for '\0'.
    memcpy(dst, src, max_chars);

    // Ensure the destination buffer is null-terminated if it was large enough.
    // If dst_size was exactly max_chars + 1 (i.e., strlen(src) + 1), this works.
    // If dst_size was larger than needed, we still need to ensure '\0' is present.
    if (dst_size > max_chars + 1) {
        // We have extra space at the end. Ensure null termination.
