def generate_token():
    """Generate a cryptographically secure random token for anti-CSRF."""
    return os.urandom(32)

@app.route('/comment', methods=['POST'])
def comment():
    # Get the CSRF token from the session if present, otherwise return 403 Forbidden
    csrf_token = session.get('csrf_token')
    if not csrf_token:
        return redirect(url_for('login'))  # Redirect to login page

    # Verify the incoming POST request against the stored token using HmacSHA256
    expected_token = generate_token()
    actual_hash = hmac.new(
        csrf_token.encode(),
        data=request.form.get('body', ''),
        digestmod='sha256'
    ).hexdigest()

    if not hmac.compare_digest(expected_token, actual_hash):
        return redirect(url_for('login'))  # Revert to login on mismatch

    # Store the comment only in session (not a database)
    session['comment'] = request.form.get('body', '')

    return render_template('comments.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        # Placeholder for password verification logic
