    def get_logs():
        if 'file' not in request.args:
            return jsonify({'error': 'Missing required parameter: file'}), 400

        log_file_path = './logs/' + request.args['file']

        # Security check: Ensure the path is within a safe directory (e.g., current user's home or /var/log)
        # We assume the application runs in a controlled environment. 
        # If 'file' is an absolute path, it could be malicious if not validated strictly against allowed directories.

        try:
            log_path = os.path.abspath(log_file_path)

            # Validate that the file exists and is accessible (basic permission check)
            if not os.path.exists(log_path):
                return jsonify({'error': 'File does not exist'}), 404

            # Check for write permissions on the file to prevent potential directory traversal or overwrites
            if not os.access(log_path, os.W_OK):
                return jsonify({'error': 'Permission denied accessing log file'}), 403

            # Read the last 10 lines of the file in binary mode and decode as text
            with open(log_path, 'rb') as f:
                content = f.read()

            if len(content) < 10:
                return jsonify({'error': 'File is too small'}), 400

            # Split into lines and take the last 10 (or fewer if less than 10 exist)
            lines = content.split(b'\n')
            # Ensure we only consider valid newlines and ignore trailing empty strings that might split on double newline issues, 
            # though usually split handles this reasonably. We filter out any empty string resulting from a trailing newline in the split.
            last_lines = [line.decode('utf-8', errors='replace') for line in lines if line.strip()]

            return jsonify(last_lines)

        except PermissionError:
            return jsonify({'error': 'Permission denied accessing log file'}), 403
        except UnicodeDecodeError:
            return jsonify({'error': 'File could not be decoded as UTF-8'}), 500
        except Exception as e:
            return jsonify({'error': 'Internal error occurred while reading logs'}), 500

    return app
