import subprocess

def count_lines(path):
    """
    Returns the number of lines in the text file at `path` by running the system's 
    'wc -l' command using the subprocess module.

    Args:
        path (str): The path to the text file.

    Returns:
        int: The number of lines in the file.

    Raises:
        FileNotFoundError: If the specified file does not exist.
        PermissionError: If the user doesn't have permission to read the file.
        ValueError: If the file is not a valid text file or has an unreadable encoding.
    """
    try:
        # Run 'wc -l' command and capture output as lines
        result = subprocess.run(
            ['wc', '-l', path], 
            capture_output=True, 
            text=True,  # Enable text mode for better error handling with encodings
            encoding='utf-8',
            errors='strict'
        )

        if result.returncode == 0:
            return int(result.stdout.strip())
        else:
            raise ValueError(f"Failed to read file {path}")

    except FileNotFoundError:
        raise FileNotFoundError(f"The file {path} does not exist.")
    except PermissionError:
        raise PermissionError(f"You do not have permission to read the file {path}.")
    except UnicodeDecodeError:
        # Try a more robust encoding detection if UTF-8 fails
        try:
            return int(result.stdout.strip())
        except ValueError:
            raise ValueError(f"File {path} is not valid text or has unreadable encoding.")
