import subprocess
import sys
import hashlib

def file_checksum(path):
    """
    Returns the SHA-256 checksum of the file at `path` as a lowercase hex string.

    Args:
        path (str): The path to the file.

    Returns:
        str: SHA-256 checksum in lowercase hexadecimal format.
    """
    try:
        # Check if the path exists and is a file
        if not Path(path).exists():
            raise FileNotFoundError(f"File not found: {path}")
        if not Path(path).is_file():
            raise IsADirectoryError(f"Path is not a file: {path}")

        # Run sha256sum command and capture the output
        result = subprocess.run(
            ['sha256sum', path],
            capture_output=True,
            text=True,
            check=False  # Don't raise exception on non-zero exit code
        )

        if result.returncode != 0:
            raise RuntimeError(f"Error while computing checksum for {path}: \n{result.stderr}")

        # Extract the hash from the output (format: "hash  filename")
        parts = result.stdout.strip().split(None, 1)
        if len(parts) > 1:
            return parts[0].lower()
        else:
            raise RuntimeError("Unexpected output format from sha256sum")

    except FileNotFoundError as e:
        raise
    except IsADirectoryError as e:
        raise
    except RuntimeError as e:
        raise

# Example usage (optional):
if __name__ == "__main__":
    if len(sys.argv) > 1:
        try:
            checksum = file_checksum(sys.argv[1])
            print(checksum)
        except FileNotFoundError:
            print("Error: File not found.", file=sys.stderr)
            sys.exit(1)
        except IsADirectoryError:
            print("Error: Path is a directory.", file=sys.stderr)
            sys.exit(1)
        except RuntimeError as e:
            print("Error computing checksum:", e, file=sys.stderr)
