import os
from pathlib import Path


def cache_put(key: str, value) -> None:
    """Stores `value` under the string `key` in the existing directory `./cache/`."""
    cache_dir = Path("./cache")
    # Ensure the cache directory exists
    if not cache_dir.exists():
        cache_dir.mkdir(parents=True)

    # Convert value to JSON-serializable format (handles all standard Python types)
    serializable_value = convert_to_serializable(value)

    # Write to a file in the cache directory
    file_path = str(cache_dir / f"{key}.json")
    with open(file_path, 'w') as f:
        json.dump(serializable_value, f)


def cache_get(key: str) -> |str | int | bool | list | dict | None:
    """Returns the stored value under `key`, or `None` if not in cache."""
    cache_dir = Path("./cache")
    file_path = str(cache_dir / f"{key}.json")

    if not os.path.exists(file_path):
        return None

    try:
        with open(file_path, 'r') as f:
            value = json.load(f)
        return convert_from_serializable(value)
    except (json.JSONDecodeError, KeyError):
        return None


def convert_to_serializable(obj):
    """Convert Python types to JSON-serializable equivalents."""
    if isinstance(obj, str):
        return obj
    elif isinstance(obj, int):
        return obj
    elif isinstance(obj, bool):
        return obj
    elif isinstance(obj, float):
        return obj
    elif isinstance(obj, list):
        return [convert_to_serializable(item) for item in obj]
    elif isinstance(obj, dict):
        return {k: convert_to_serializable(v) for k, v in obj.items()}
    else:
        raise TypeError(f"Type {type(obj)} is not JSON serializable")


def convert_from_serializable(obj):
    """Convert JSON-serializable types back to Python equivalents."""
    if isinstance(obj, str):
        return obj
    elif isinstance(obj, int):
        return int(obj)
    elif isinstance(obj, bool):
        return bool(obj)
    elif isinstance(obj, float):
        return float(obj)
    elif isinstance(obj, list):
        return [convert_from_serializable(item) for item in obj]
    elif isinstance(obj, dict):
        return {k: convert_from_serializable(v) for k, v in obj.items()}
    else:
        raise TypeError(f"Type {type(obj)} is not JSON serializable")
