    return f"data:{serialized}"

def restore_cart(cookie_value):
    """Converts the cookie string sent back by the browser into the list of dicts."""
    if not isinstance(cookie_value, str):
        raise TypeError("cookie_value must be a string")

    try:
        data = json.loads(cookie_value)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in cookie: {e}")

    if data is None or not isinstance(data, dict):
        raise ValueError("Cookie value must be a valid JSON object")

    # Check for 'data:' prefix to ensure it's the full serialized string format
    if not data.startswith('data:'):
        raise ValueError("Invalid cookie format. Expected 'data:<json>.'")

    items = json.loads(data[5:])  # Remove "data:" and parse JSON

    return items
