void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    /* Ensure there is enough space for: '[' + level + ']' + '\n' + message */
    size_t required_len = 1; /* for '[' */
    required_len += strlen(level);   /* length of level */
    required_len += 2; /* for ']']\n */
    required_len += strlen(message); /* length of message */

    if (out_len < required_len) {
        return; /* Cannot write the log line */
    }

    out[0] = '[';
    size_t idx = 1;
    while (*level && idx + strlen(level) <= out_len) {
        *out++ = level[idx++];
    }
    out[idx++] = ']';

    if (*message == '\0') {
        out[idx] = '\0'; /* Ensure null-termination */
    } else {
        while (*message && idx + strlen(message) <= out_len) {
            *out++ = message[idx++];
