        if (*message) {
            out[idx++] = '\0'; /* Null terminate the message part */
        }
    }

    /* Ensure the buffer ends with a null terminator */
    if (out_len > 1 && out[out_len - 1] != '\n') {
        out[out_len - 1] = '\0';
    } else {
        out[out_len - 1] = '\0';
