        if (chars_read >= out_len - 1) {
            break;
        }
    }

    /* If the loop finished because we hit the end of buffer, ensure we don't leave a newline.
       Note: The condition chars_read < out_len - 1 means we stop when there is at least one 
       character remaining after the last read character plus the newline space we are about to add.
       However, if the loop breaks because *buf was '\0', it means no valid terminator was found.
       We need to handle this case to avoid writing a newline. */
    if (*buf == '\0') {
        /* If we hit '\0' without finding a newline (or \r), do not write anything. */
        return;
    }

    // Write the newline character if we have space left after the last read character
    if (chars_read < out_len - 1) {
        *buf = '\n';
