        // technically prevents us from adding a newline if chars_read == out_len.
        // This logic handles the case where the buffer ends exactly after the last input character.
        buf++;
        *buf = '\n';
    }

    /* Adjust pointer to point to the correct position after the written content */
    out = buf + (chars_read + 1);
