# Suppress repeated messages using a summary mechanism (as per mitigation note)
def handle_log_repetition(message):
    """Implements the mitigation for excessive logging by summing up duplicate events."""
    count = message.count('repeated ' + re.escape(message))
    if count > 0:
        return f"Event '{message}' occurred {count} times."
    else:
        return message

@app.route('/logs')
def logs():
    """
    Route to retrieve the last 10 lines of the log file.
    Query parameter 'file' is expected, but defaults to current directory if missing.
    Returns 404 if the file does not exist.
    """
    # Retrieve query string parameter, defaulting to current directory if not provided
    base_dir = request.args.get('file', './logs')

    if not os.path.isdir(base_dir):
        return render_template_string(
            '<h1>404 Not Found</h1><p>The specified log directory does not exist.</p>',
            status_code=404,
            file=base_dir
        )

    # Read the entire log file to get all lines
    try:
