import subprocess

def count_lines(path: str) -> int:
    """Count the number of lines in a text file using the system's 'wc -l' command."""
    try:
        # Run 'wc -l' on the file path and get its output (line count string)
        result = subprocess.run(
            ['wc', '-l', path],
            check=True,
            capture_output=True
        )
        lines_str = result.stdout.decode('utf-8')
        # 'wc -l' returns the line count followed by newline characters and possibly other info
        if not lines_str:
            return 0
        parts = lines_str.split(None, 1)
        if len(parts) > 1:
            try:
                return int(parts[1])
            except ValueError:
                # Fallback: if parsing fails, assume the first non-empty part is the count
                return len(parts[0].strip()) if parts[0] else 0
        else:
            # No second part after split(None, 1), just return length of the string
            try:
                return int(lines_str)
            except ValueError:
                return len(lines_str)
    except subprocess.CalledProcessError:
        raise FileNotFoundError(f"Could not access file: {path}")
