def load_params(path: str) -> Dict[str, List[float]]:
    """Loads a file containing layer parameters (dict mapping strings to lists of floats) and returns the dict."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)

            # Validate that loaded data is a dict where keys are strings and values are lists of floats
            if not isinstance(data, dict):
                raise ValueError("Expected input file to be a JSON object.")
            for key, value in data.items():
                if not isinstance(key, str):
                    raise ValueError(f"JSON object must have string keys. Found: {type(key)}")
                if not isinstance(value, list):
                    raise ValueError(f"JSON object values must be lists. Found: {type(value)}")
                for item in value:
                    if not isinstance(item, (int, float)):
                        raise ValueError(f"JSON object values must be numeric. Found: {type(item)}")
            return data

    except FileNotFoundError:
        raise FileNotFoundError("The specified path does not exist.")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format in the file: {e}")
