 * Copies string src into dst, converting every alphabetic character to uppercase.
 * 
 * If any character is not a letter, it remains unchanged.
 * If the length of src exceeds dst_size, only the first dst_size bytes are copied.
 * Returns 0 on success, -1 on failure (e.g., memory allocation or write error).
 */
static int to_upper_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || src == NULL || dst_size == 0) {
        return -1;
    }

    size_t copy_len = dst_size;
    if (copy_len > src_len(src)) {
        copy_len = src_len(src);
    }

    for (; copy_len > 0; --copy_len) {
        char *p = &src[0];
        for (; p < src + copy_len; ++p) {
            if (*p == '\0') {
                break;
            }
            /* Convert letter to upper case */
            if (isupper((unsigned char)*p)) {
                *p = toupper((unsigned char)*p);
            } else if (!isalpha((unsigned char)*p)) {
                /* Non-letter characters remain unchanged */
                continue;
            }
        }

        /* Safety check after loop: if src was shorter than expected, we stop early.
         * This prevents overwriting beyond the intended range. */
        if (copy_len == 0) {
            break;
        }

        if (*p != '\0') {
            dst[0] = *p;
            ++dst;
        } else {
            /* Reached end of src without writing a character to dst */
            break;
        }
    }

    return 0;
}

/** Helper macro for string length (optional but useful) */
