    if (dst == NULL || src == NULL || dst_size == 0) {
        return; // Do nothing on invalid inputs
    }

    void (*to_upper_copy)(char *, size_t, const char *) = to_upper_copy;
    if (to_upper_copy(dst, dst_size, src) == 0) {
        /* Success */
    } else {
        /* Failure: write error or allocation issue */
        return;
    }
