    /* Split the string at the first '=' */
    const char *key = line + 1;      // After '='
    const char *value_start = key + (len - equals_pos);

    /* Ensure we don't read beyond the actual value length */
    size_t key_len = strlen(key);
    size_t value_len = strlen(value_start);

    if (key_len == 0) {
