    # Check if the path exists (handles case where user passed an absolute or relative path)
    if not os.path.exists(file_path):
        return jsonify({'error': 'File not found'}), 404

    try:
        # Use subprocess to read the file in binary mode to ensure proper handling of UTF-8/other encodings
        # -r : raw mode (treat input as bytes)
        # shell=True is generally discouraged but necessary for this specific use case 
        # where we need to pass a path via command line to 'cat' which might not accept arguments directly in the URL.
        process = subprocess.Popen(
            ['cat', file_path], 
            stdout=subprocess.PIPE, 
            stderr=subprocess.PIPE, 
            text=True
        )

        stdout, stderr = process.communicate()

        if process.returncode == 0:
            lines = stdout.strip().split('\n')
            # Filter empty lines and take the last 10 non-empty lines
            log_lines = [line for line in reversed(lines) if line]

            if len(log_lines) <= 10:
                return jsonify({'error': 'Less than 10 lines found'}), 400

            return ''.join(log_lines[-10:])
        else:
            # Check if stderr contains errors that indicate the file is not readable or exists but isn't a log file
            error_text = stderr.strip()
            if "No such file or directory" in error_text or "Permission denied" in error_text:
                return jsonify({'error': 'File access denied or path invalid'}), 403
            else:
                return jsonify({'error': 'Error reading log file'}), 500

    except PermissionError:
        return jsonify({'error': 'Permission denied'}), 403
    except Exception as e:
        return jsonify({'error': 'Internal error'}), 500

