import os
import shutil
from pathlib import Path

def delete_cache_entry(key):
    """
    Deletes the file named 'key' from the directory './cache/'.

    Parameters:
    key (str): The name of the file to delete.

    Returns:
    bool: True if a file was deleted and False otherwise.

    Raises:
    FileNotFoundError: If the specified file does not exist.
    PermissionError: If there is insufficient permission to delete the file.
    """
    cache_dir = Path("./cache")

    # Normalize the path to ensure consistency
    cache_path = cache_dir / key

    # Check if the path exists and is a file
    if not cache_path.exists():
        return False

    if cache_path.is_file():
        try:
            cache_path.unlink()
            return True
        except PermissionError:
            return False
        except Exception:
            return False
    else:
        # If it's a directory, delete everything inside and the current directory itself
        for item in list(cache_path.iterdir()):
            try:
                if item.is_file():
                    item.unlink()
            except PermissionError:
                pass  # Silently ignore permission errors when deleting files
            else:
                try:
                    shutil.rmtree(item)
                except PermissionError:
                    pass  # Silently ignore permission errors when removing directories
        try:
            cache_path.rmdir()
        except PermissionError:
            return False
        return False
