import subprocess
from pathlib import Path


def disk_usage(directory):
    """
    Returns the human-readable total size of the given directory as reported by 'du -sh'.

    Args:
        directory (str): The path to the directory.

    Returns:
        str: A string representing the size in a human-readable format (e.g., "12K").
    """
    try:
        # Create the du command with -s (no summary) and -h (human-readable) flags
        result = subprocess.run(
            ["du", "-sh", directory],
            capture_output=True,
            text=True,
            check=False  # Don't raise exception if output is empty or fails in some ways
        )

        if not result.returncode == 0:
            return "Unknown"  # Fallback for unexpected errors

        output = result.stdout.strip()

        if not output:
            return "Unknown"

        # The du -sh command returns something like "1.2K" or "12K" or "45M"
        # We need to parse this string manually based on common patterns
        parts = output.split(" ")
        if len(parts) < 2:
            return "Unknown"

        size_str = parts[0].lstrip('-').rstrip('.')

        if not size_str:
            return "Unknown"

        # Determine unit and numeric value
        if size_str == 'K':
            value = float(parts[1])
            unit = 'K'
        elif size_str == 'M':
            value = float(parts[1]) * 1024
            unit = 'M'
        elif size_str == 'G':
            value = float(parts[1]) * 1024 * 1024
            unit = 'G'
        else:
            # Try to handle numbers like "123" or "45678" followed by unit
            try:
                value = float(size_str)
                unit = parts[1] if len(parts) > 1 else None
            except ValueError:
                return "Unknown"

        # Construct the final string
        if unit == 'K':
            return f"{value}K"
        elif unit == 'M':
            return f"{value:.2f}M"  # Round to 2 decimal places for cleanliness
        elif unit == 'G':
            return f"{value:.2f}G"
        else:
            return str(value)

    except FileNotFoundError:
        return "Error: 'du' command not found. Ensure it is installed."
    except Exception as e:
        return str(e)
