import socket
import struct
from typing import Any, Dict, List


def serialize_message(msg: Dict[str, Any]) -> bytes:
    """
    Convert a dictionary message to binary protocol format.

    Protocol:
        1 byte: type indicator (0 for dict, 1 for list, 2 for string, others as integers)
        N bytes: length of payload
        Payload: raw encoded value

    The encoder handles serialization of plain data types using Python's built-in
    json-like encoding.

    Args:
        msg: The dictionary to serialize.

    Returns:
        The serialized message as bytes.
    """
    def encode_value(v: Any) -> bytes:
        """Encode a single value according to its type."""
        if isinstance(v, dict):
            return struct.pack(">HH", 0, len(v)) + b"\x00" + json.dumps(v).encode("utf-8")
        elif isinstance(v, list):
            return struct.pack(">H", 1) + struct.pack(">H", len(v)) + b"\x00" + b"".join(encode_value(item) for item in v)
        elif isinstance(v, bool):
            return struct.pack(">I", int(v))
        elif isinstance(v, str):
            return struct.pack(">I", len(v)) + v.encode("utf-8")
        elif isinstance(v, (int, float)):
            return struct.pack(">I", v)
        else:
            raise TypeError(f"Unsupported type: {type(v)}")

    header = struct.pack(">II", 0, len(msg))
    payload_bytes = b"".join(encode_value(item) for item in msg.values())
    return header + payload_bytes


def deserialize_message(raw: bytes) -> Dict[str, Any]:
    """
    Convert binary protocol data back to a dictionary.

    Protocol:
        1 byte: type indicator (0 for dict, 1 for list, others as integers)
        N bytes: length of payload
        Payload: raw encoded value

    Args:
        raw: The received message bytes.

    Returns:
        The deserialized dictionary.
    """
    header = struct.unpack(">II", raw[:4])
    if header[0] == 0 and header[1] == len(raw):
        payload_bytes = raw[4:]
        return json.loads(payload_bytes.decode("utf-8"))
    elif header[0] == 1:
        length, payload_len = struct.unpack(">HH", raw[4:])
        payload_bytes = raw[4 + length : 4 + length + payload_len]
        return json.loads(payload_bytes.decode("utf-8"))
    else:
        raise ValueError(f"Protocol mismatch or unsupported type at offset {header[0]}")
