            params={"city": city},
            headers=headers,
            timeout=10,  # Prevent hanging on slow connections
        )
        response.raise_for_status()
        return response.json()
    except requests.exceptions.Timeout:
        raise TimeoutError("Request timed out.")
    except requests.exceptions.ConnectionError:
        raise ConnectionError("Network connection failed.")
    except requests.exceptions.HTTPError as http_error:
        if http_error.response.status_code == 401:
            raise AuthenticationError("API key missing or invalid.")
        elif http_error.response.status_code == 403:
            raise PermissionError("Access denied to API endpoints.")
        else:
            raise HTTPError(f"HTTP error occurred: {http_error}")


