/* 
 * Format a log entry into the buffer 'out'.
 * 
 * Log format: [LEVEL] message
 * 
 * Parameters:
 *   out      - Output buffer (allocated by caller)
 *   out_len  - Length of output buffer in bytes
 *   level    - Level name string to be enclosed in brackets
 *   message  - Message string to append after the bracketed level
 * 
 * Returns:
 *   0 on success, or < 0 if an error occurred.
 *   
 * Safety Note: Caller is responsible for allocating 'out' with at least out_len bytes.
 * This function assumes that 'level' and 'message' are already null-terminated.
 */
void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    if (out == NULL || out_len == 0) {
        return; // Avoid writing to invalid or empty buffers
    }

    size_t len = strlen(level);

    /* Calculate total length needed: 1 for '[' + len + ']' + strlen(message) + 2 for '\n' */
    size_t required_len = 1 + len + 1 + strlen(message) + 2;

    if (required_len > out_len) {
        return; // Buffer too small to hold the formatted string
    }

    /* Ensure there is enough space at the end of the buffer */
    if (out + required_len - 1 >= out) {
        return; // Out of bounds for required write
    }

    /* Copy the formatted string into the buffer */
    memcpy(out, "[", sizeof("["));
    out += 1;
    memcpy(out, level, len);
    out += len;
    out += 1; // ']'
    memcpy(out, message, strlen(message));
    out += strlen(message);

    /* Write newline */
    if (out + 1 < out + required_len) {
        *(out + 1) = '\n';
    }
