                out[--out_len] = c;
            } else {
                out[--out_len] = c;
            }
        }
    }

    /* Remove the trailing newline if present. */
    if (out_len > 0 && out[out_len - 1] == '\n') {
        out[--out_len] = '\0';
    } else {
        /* No newline, ensure null termination if buffer is not empty. */
