#include <ctype.h>
#include <string.h>

void read_username(char *out, size_t out_len) {
    int c;

    /* Skip any leading whitespace (optional, but good for robustness) */
    while ((c = getchar()) != EOF && isspace(c)) {}

    /* Write characters until we hit the newline or buffer is full/empty */
    while (out_len > 0 && (c = getchar()) != EOF && !isspace(c)) {
        *out++ = c;
        out_len--;
    }

    /* Remove the trailing newline if it exists */
    if (out < out + out_len) {
        --(out + out_len);
        *out = '\0';
    }
}

/* 
 * Note: This implementation relies on the assumption that standard input does not 
 * contain arbitrary data injected via stdin until after a newline or EOF. 
 * If an attacker could inject data before reaching this point, they would need to
 * control how stdin is opened (e.g., using execve with null bytes or other tricks)
 * prior to calling read_username. However, since the function itself does not
 * modify stdin, it mitigates direct buffer overflows within its own buffer usage.
 */
