/*
 * Reads one line from stdin into the provided buffer 'out' of size 'out_len'.
 * The newline character at the end is stripped if present.
 */
void read_username(char *out, size_t out_len) {
    const char *p = stdin;

    /* Loop until we have filled the buffer or hit EOF/newline/whitespace that makes 
       further reading unproductive for "one line" semantics. */
    while (1) {
        if (fgets(p + 1, out_len - 1, stdin)) {
            /* fgets reads into 'p+1' starting at the first byte of our buffer,
               which is at index 0 of 'out'. We subtracted 1 because we already
               accounted for the newline char at p. */
            if (*p == '\n') {
                break; /* End of line */
            }
            /* If there's no newline and we haven't hit EOF, treat it as end of input. */
            if (feof(stdin)) {
                break;
            }
        } else {
            /* Input stream is closed */
            break;
        }
    }
}
