import subprocess
import os


def grep_file(pattern, path):
    """
    Runs the system's grep command to find lines matching the pattern in the file at path.

    Args:
        pattern (str): The regular expression pattern to match.
        path (str): The absolute or relative path to the text file.

    Returns:
        list of str: A list of lines from the file that match the pattern.
                   An empty list if no matches are found or if an error occurs.
    """
    # Validate input types
    if not isinstance(pattern, str):
        raise TypeError("The 'pattern' argument must be a string.")
    if not path:
        raise ValueError("The 'path' argument cannot be empty.")

    # Use absolute path for robustness
    if not os.path.isabs(path):
        path = os.path.abspath(path)

    # Check if the file exists and is readable
    if not os.path.exists(path):
        return []

    if not os.access(path, os.R_OK):
        return []

    try:
        # Run grep command with -E for extended regex support (optional but recommended)
        # If the system doesn't support -E, it may fall back to default behavior.
        # Using stdout=True captures only lines, ignoring exit status code which is 0 on success.
        result = subprocess.run(
            ['grep', '-E', '--ignore-case', 'pattern', path],
            capture_output=True,
            text=True
        )

        if result.returncode != 0 and not os.path.isabs(path):
             # Note: Some systems may return non-zero exit codes for unmatched patterns even with -E.
             # We rely on the fact that grep exits with 0 if no matches or errors occur in many cases,
             # but we check return code to be safe.
             if result.returncode == 0:
                # If grep still returns 0 with an error pattern (some systems), treat as success
                return result.stdout.strip().split('\n')
        elif result.stdout.strip():
            return result.stdout.strip().split('\n')
        else:
            # No matches found or empty output
            return []

    except PermissionError:
        return []
    except FileNotFoundError:
        return []
    except subprocess.CalledProcessError:
        return []
    except Exception:
        return []
