from typing import Any, Dict, Optional

class SmallFileCache:
    def __init__(self, cache_path: str = "./cache"):
        """Initialize the cache with a specified path."""
        self.cache_path = cache_path
        self._cache_dir = os.path.dirname(cache_path)
        if not os.path.exists(self._cache_dir):
            os.makedirs(self._cache_dir, exist_ok=True)

    def _load_from_file(self, key: str) -> Optional[Any]:
        """Load value from a local file."""
        filepath = os.path.join(self._cache_dir, f"{key}.json")
        if not os.path.exists(filepath):
            return None

        try:
            with open(filepath, 'r') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data.get(key)  # Return the value associated with the key from the dict
            elif isinstance(data, list):
                for item in data:
                    if isinstance(item, dict) and item.get('key') == key:
                        return item.get('value')
            return data.get(key)
        except (json.JSONDecodeError, KeyError):
            return None

    def _save_to_file(self, key: str, value: Any) -> None:
        """Save value to a local file."""
        filepath = os.path.join(self._cache_dir, f"{key}.json")

        try:
            data = {}
            if isinstance(value, dict):
                for k, v in value.items():
                    data[k] = v
            else:
                data[key] = value

            with open(filepath, 'w') as f:
                json.dump(data, f)
        except IOError:
            pass  # Silently ignore file write errors to prevent crashes

    def cache_put(self, key: str, value: Any) -> None:
        """Stores `value` under the string `key`."""
        self._save_to_file(key, value)

    def cache_get(self, key: str) -> Optional[Any]:
        """Returns the stored value, or `None` if the key is not in the cache."""
        return self._load_from_file(key)
