import os
from typing import Any, Optional


def cache_put(key: str, value: Any) -> None:
    """Stores a value under the given key in the local cache directory."""
    cache_dir = "./cache"
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir, exist_ok=True)

    filepath = os.path.join(cache_dir, f"{key}.txt")

    # Simple text-based cache: value is stored as a single line of JSON with metadata
    # This avoids storing raw sensitive data on disk while keeping it simple.
    # For stricter security requirements, you could use encrypted files here.
    data = {
        "type": "text",
        "value": str(value) if not isinstance(value, (str, int, float, bool)) else value,
        "timestamp": os.path.getmtime(filepath),
        "created_at": os.path.getctime(filepath),
    }

    with open(filepath, "w") as f:
        f.write(f"{{data}}\n")


def cache_get(key: str) -> Optional[Any]:
    """Returns the stored value under the given key, or None if not found."""
    cache_dir = "./cache"
    if not os.path.exists(cache_dir):
        return None

    filepath = os.path.join(cache_dir, f"{key}.txt")

    if not os.path.exists(filepath):
        return None

    with open(filepath, "r") as f:
        line = f.readline()

    if not line.strip():
        return None

    try:
        import json
        data = json.loads(line)

        if data.get("type") == "text":
