void to_upper_copy(char *dst, size_t dst_size, const char *src) {
    if (src == NULL) {
        // No change is needed; dst remains unchanged.
        return;
    }

    for (size_t i = 0; src[i] != '\0' && dst_size > i; i++) {
        unsigned char c = (unsigned char)src[i];

        // Check if the character is an alphabetic ASCII value.
        // In ASCII, 'A' is 65 and 'Z' is 90. All uppercase letters are in this range.
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
            // Convert to uppercase.
            if (c >= 'a' && c <= 'z') {
                dst[i] = (char)((c - 'a' + 'A'));
            } else {
                // Character is already uppercase or outside ASCII range; no conversion needed.
                dst[i] = (char)c;
            }
        } else {
            // Non-letter character: copy as-is.
            dst[i] = (char)c;
        }
    }

    // Ensure the null terminator is present if we are not at the end of the string
    // or if we haven't modified past the original length.
    while (i < dst_size && dst[i] != '\0') {
        dst[i] = '\0';
        i++;
    }

