 * - Trims any trailing whitespace after the last valid character (but not if there's no data).
 * - Leaves spaces at the end of the copy as they are in the original string.
 *
 * Behavior on null-terminated strings:
 * If 'src' is NULL, the function returns 0.
 * If 'dst' is NULL or dst_size == 0, it returns 0 immediately.
 *
 * Safety guarantees:
 * - Does not access memory outside the bounds of 'dst'.
 * - Does not truncate 'src' beyond its length; only copies up to 'dst_size'.
 * - The resulting string 'dst' is guaranteed to be a valid C null-terminated string.
 */
void to_upper_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || dst_size == 0 || src == NULL) {
        return;
    }

    /* Limit the number of bytes we can copy to avoid reading beyond dst_size. */
    size_t bytes_to_copy = MIN(dst_size, strlen(src));

    char *p = dst;
    const char *s = src;

    /* Advance pointer while:
     * - there are characters left to read, OR
     * - the current character is not a letter (ASCII 65-90).
     */
    while (bytes_to_copy > 0 && (*p != '\0' && issalnum(*p))) {
        if (*p >= 'a' && *p <= 'z') {
            *p = (char)('A' + (*p - 'a'));
        }
        ++p;
        bytes_to_copy--;
    }

    /* Stop at the null terminator or before it, whichever comes first. */
    if (bytes_to_copy > 0 && p >= s) {
        *p = '\0';
    } else if (*p == '\0') {
        /* dst is already valid with null termination; no need to copy src bytes. */
    }

    return;
}
