void to_upper_copy(char *dst, size_t dst_size, const char *src) {
    if (src == NULL || dst == NULL) {
        return;
    }

    size_t i = 0;
    while ((i < src_size(src)) && (i < dst_size(dst))) {
        unsigned char c = (unsigned char) src[i];
        if (c >= 'a' && c <= 'z') {
            c = (unsigned char) ('A' + c - 'a');
        }
        // Ensure the character fits within ASCII printable range for valid string output.
        // If it exceeds, we simply skip/ignore it rather than copying a non-ASCII byte,
        // which is safer than potentially overwriting memory unexpectedly.
        if (c < 32) {
            i++;
            continue;
        }
        dst[i++] = c;
    }

    // Ensure the null terminator is written at the correct position.
    dst[i] = '\0';
