#include <stdio.h>

/*
 * Reads one line from stdin into the provided buffer, preserving its length.
 * Strips any trailing newline character if present.
 *
 * Parameters:
 *   out  - pointer to the output buffer (char *)
 *   out_len - size of the buffer in bytes (size_t)
 *
 * Behavior:
 *   - Returns the number of characters successfully stored in 'out'.
 *   - If EOF is reached before filling the buffer, returns EOF.
 *   - If a line has no newline, the newline character is not added to 'out';
 *     it is only counted as part of the returned length.
 *
 * Note:
 *   This implementation assumes the input source is reliable (e.g., stdin)
 *   and does not perform any network I/O or external file operations.
 */

void read_username(char *out, size_t out_len) {
    int c;
    unsigned char buffer[256];  /* Use a fixed-size array to avoid stack overflow from repeated allocations */

    /* Read characters until EOF or newline is encountered */
    while ((c = getchar()) != '\n' && c != EOF) {
        if (out_len > 0 && out + (size_t)c <= out + out_len) {
            *(buffer++ - c) = c;
        } else if (c == EOF) {
            /* EOF reached without newline or before buffer was full */
            break;
        } else {
            /* Out of buffer space while reading, stop here */
            break;
        }

        --out_len;
    }

    /* Remove the trailing newline if it was present in the input stream */
    /* If c == '\n', remove it from 'out' and decrement length by 1. */
    /* Otherwise, do nothing (the newline is not part of the line content). */
    if (c == '\n') {
        --out_len;
        out[out_len - 1] = 0;  /* Ensure null-termination if we successfully placed a char there */
    } else if (c != EOF) {
        /* If we hit EOF before seeing the newline, ensure buffer is null-terminated. */
        while ((buffer[--out_len] - out_len) == 0 && out_len > 0) {
            /* Avoid underflow when checking if a char was placed at the end of buffer */
            break;
        }
    }

    /* Ensure the output string is properly null-terminated. */
    if (out + out_len <= out + out_len + sizeof(char)) {
        *(out + out_len) = '\0';
    }
}
